-- Створення таблиць і заповнення бази даних тестовими даними та створення індексів.
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "couriers" (
	"courier_id"	INTEGER,
	"first_name"	TEXT NOT NULL,
	"last_name"	TEXT NOT NULL,
	"phone"	TEXT NOT NULL UNIQUE,
	PRIMARY KEY("courier_id")
);
CREATE TABLE IF NOT EXISTS "customers" (
	"customer_id"	INTEGER,
	"first_name"	TEXT NOT NULL,
	"last_name"	TEXT NOT NULL,
	"phone"	TEXT NOT NULL UNIQUE,
	"email"	TEXT NOT NULL UNIQUE,
	PRIMARY KEY("customer_id")
);
CREATE TABLE IF NOT EXISTS "delliveries" (
	"dellivery_id"	INTEGER,
	"order_id"	INTEGER NOT NULL,
	"courier_id"	INTEGER NOT NULL,
	"dellivery_address"	TEXT NOT NULL,
	"dellivery_date"	TEXT NOT NULL,
	"dellivery_status"	TEXT NOT NULL,
	PRIMARY KEY("dellivery_id"),
	FOREIGN KEY("courier_id") REFERENCES "couriers"("courier_id"),
	FOREIGN KEY("order_id") REFERENCES "orders"("order_id")
);
CREATE TABLE IF NOT EXISTS "order_items" (
	"order_item_id"	INTEGER,
	"order_id"	INTEGER NOT NULL,
	"product_id"	INTEGER NOT NULL,
	"quantity"	INTEGER NOT NULL,
	"price"	REAL NOT NULL,
	PRIMARY KEY("order_item_id"),
	FOREIGN KEY("order_id") REFERENCES "orders"("order_id"),
	FOREIGN KEY("product_id") REFERENCES "products"("product_id")
);
CREATE TABLE IF NOT EXISTS "orders" (
	"order_id"	INTEGER,
	"customer_id"	INTEGER NOT NULL,
	"order_date"	TEXT NOT NULL,
	"order_status"	TEXT NOT NULL,
	PRIMARY KEY("order_id"),
	FOREIGN KEY("customer_id") REFERENCES "customers"("customer_id")
);
CREATE TABLE IF NOT EXISTS "payments" (
	"payment_id"	INTEGER,
	"order_id"	INTEGER NOT NULL,
	"payment_date"	TEXT NOT NULL,
	"amount"	REAL NOT NULL,
	"payment_status"	TEXT NOT NULL,
	PRIMARY KEY("payment_id"),
	FOREIGN KEY("order_id") REFERENCES "orders"("order_id")
);
CREATE TABLE IF NOT EXISTS "products" (
	"product_id"	INTEGER,
	"product_name"	TEXT NOT NULL,
	"price"	REAL NOT NULL,
	PRIMARY KEY("product_id")
);

CREATE INDEX IF NOT EXISTS "idx_delliveries_courier_id" ON "delliveries" (
	"courier_id"
);
CREATE INDEX IF NOT EXISTS "idx_delliveries_order_id" ON "delliveries" (
	"order_id"
);
CREATE INDEX IF NOT EXISTS "idx_order_items_order_id" ON "order_items" (
	"order_id"
);
CREATE INDEX IF NOT EXISTS "idx_order_items_product_id" ON "order_items" (
	"product_id"
);
CREATE INDEX IF NOT EXISTS "idx_orders_customer_id" ON "orders" (
	"customer_id"
);
CREATE INDEX IF NOT EXISTS "idx_payments_order_id" ON "payments" (
	"order_id"
);
COMMIT;
